class Solution {
public:
    vector<int> solve(vector<int>& nums, vector<vector<int>>& queries) {
        const int MOD = 1000000007;
        int n = nums.size();
        int block = static_cast<int>(sqrt(n)) + 1;
        vector<vector<int>> dp(block, vector<int>(n + 1, 0));
        for (int step = 1; step < block; ++step) {
            for (int i = n - 1; i >= 0; --i) {
                dp[step][i] = (nums[i] + (i + step < n ? dp[step][i + step] : 0LL)) % MOD;
            }
        }
        vector<int> answer;
        for (const auto& query : queries) {
            int start = query[0], step = query[1];
            if (step < block) answer.push_back(dp[step][start]);
            else {
                long long sum = 0;
                for (int i = start; i < n; i += step) sum = (sum + nums[i]) % MOD;
                answer.push_back(static_cast<int>(sum));
            }
        }
        return answer;
    }
};
